∀ {scheme : SearchRouteInspectCommittedUniverse.CandidateCommitmentScheme} {root : Nat}
  {candidate : SearchRouteDAG.GraphCandidate}
  (opening : SearchRouteInspectCommittedUniverse.MembershipOpening scheme root candidate),
  scheme.contains root candidate

∀ {scheme : SearchRouteInspectCommittedUniverse.CandidateCommitmentScheme} {root : Nat}
  {candidate : SearchRouteDAG.GraphCandidate}
  (opening : SearchRouteInspectCommittedUniverse.ExclusionOpening scheme root candidate),
  ¬scheme.contains root candidate

∀ {scheme : SearchRouteInspectCommittedUniverse.CandidateCommitmentScheme} {root : Nat}
  {candidate : SearchRouteDAG.GraphCandidate}
  (opening : SearchRouteInspectCommittedUniverse.MembershipOpening scheme root candidate), scheme.validRoot root

∀ {scheme : SearchRouteInspectCommittedUniverse.CandidateCommitmentScheme} {root : Nat}
  {candidate : SearchRouteDAG.GraphCandidate}
  (opening : SearchRouteInspectCommittedUniverse.ExclusionOpening scheme root candidate), scheme.validRoot root

∀ {scheme : SearchRouteInspectCommittedUniverse.CandidateCommitmentScheme} {root : Nat}
  {candidate : SearchRouteDAG.GraphCandidate}
  (membership : SearchRouteInspectCommittedUniverse.MembershipOpening scheme root candidate)
  (exclusion : SearchRouteInspectCommittedUniverse.ExclusionOpening scheme root candidate), False

∀ {scheme : SearchRouteInspectCommittedUniverse.CandidateCommitmentScheme}
  {initial : SearchRouteInspectLoop.InspectLoopState} {snapshot : SearchRouteInspectCertifiedLedger.RankedDAGSnapshot}
  {source target : Fin snapshot.graph.nodeCount} {requirement : SearchRouteCost.RouteRequirement}
  {budget : SearchRouteDAG.GraphRouteBudget} {selected : SearchRouteDAG.GraphCandidate}
  (ledger :
    SearchRouteInspectCommittedUniverse.CommittedTraceLedger scheme initial snapshot source target requirement budget
      selected),
  ledger.coverage.claimedSnapshotDigest = snapshot.digest

∀ {scheme : SearchRouteInspectCommittedUniverse.CandidateCommitmentScheme}
  {initial : SearchRouteInspectLoop.InspectLoopState} {snapshot : SearchRouteInspectCertifiedLedger.RankedDAGSnapshot}
  {source target : Fin snapshot.graph.nodeCount} {requirement : SearchRouteCost.RouteRequirement}
  {budget : SearchRouteDAG.GraphRouteBudget} {selected : SearchRouteDAG.GraphCandidate}
  (ledger :
    SearchRouteInspectCommittedUniverse.CommittedTraceLedger scheme initial snapshot source target requirement budget
      selected),
  SearchRouteBranchBound.VisibleOptimal selected
    (SearchRouteInspectTraceCatalog.projectTraceCatalog ledger.visibleCatalog)

∀ {scheme : SearchRouteInspectCommittedUniverse.CandidateCommitmentScheme}
  {selected candidate : SearchRouteDAG.GraphCandidate}
  {frontier : SearchRouteInspectCommittedUniverse.CertifiedCommittedFrontier scheme},
  SearchRouteBranchBound.Prunable selected frontier.lowerBound →
    scheme.contains frontier.rootDigest candidate → SearchRouteDAG.graphLexNoWorse selected candidate

∀ {scheme : SearchRouteInspectCommittedUniverse.CandidateCommitmentScheme}
  {initial : SearchRouteInspectLoop.InspectLoopState} {snapshot : SearchRouteInspectCertifiedLedger.RankedDAGSnapshot}
  {source target : Fin snapshot.graph.nodeCount} {requirement : SearchRouteCost.RouteRequirement}
  {budget : SearchRouteDAG.GraphRouteBudget} {selected : SearchRouteDAG.GraphCandidate}
  (ledger :
    SearchRouteInspectCommittedUniverse.CommittedTraceLedger scheme initial snapshot source target requirement budget
      selected),
  ∃ entry, entry ∈ ledger.visibleCatalog ∧ entry.candidate = selected

∀ {scheme : SearchRouteInspectCommittedUniverse.CandidateCommitmentScheme}
  {initial : SearchRouteInspectLoop.InspectLoopState} {snapshot : SearchRouteInspectCertifiedLedger.RankedDAGSnapshot}
  {source target : Fin snapshot.graph.nodeCount} {requirement : SearchRouteCost.RouteRequirement}
  {budget : SearchRouteDAG.GraphRouteBudget} {selected : SearchRouteDAG.GraphCandidate}
  (ledger :
    SearchRouteInspectCommittedUniverse.CommittedTraceLedger scheme initial snapshot source target requirement budget
      selected),
  SearchRouteDAG.Realizes snapshot.graph source target selected

∀ {scheme : SearchRouteInspectCommittedUniverse.CandidateCommitmentScheme}
  {initial : SearchRouteInspectLoop.InspectLoopState} {snapshot : SearchRouteInspectCertifiedLedger.RankedDAGSnapshot}
  {source target : Fin snapshot.graph.nodeCount} {requirement : SearchRouteCost.RouteRequirement}
  {budget : SearchRouteDAG.GraphRouteBudget} {selected : SearchRouteDAG.GraphCandidate}
  (ledger :
    SearchRouteInspectCommittedUniverse.CommittedTraceLedger scheme initial snapshot source target requirement budget
      selected),
  (∃ entry, entry ∈ ledger.visibleCatalog ∧ entry.candidate = selected) ∧
    SearchRouteDAG.Realizes snapshot.graph source target selected ∧
      ∀ (candidate : SearchRouteDAG.GraphCandidate),
        SearchRouteDAG.Realizes snapshot.graph source target candidate →
          SearchRouteDAG.graphFeasibleB requirement budget candidate = true →
            SearchRouteDAG.graphLexNoWorse selected candidate
